public class ToStringDetectorTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    public static void main(String[] args) {
        try {
            check("a class with no toString declares none", false,
                    ToStringDetector.declaresToString(BarePojo.class));
            check("and would print Object's default", false,
                    ToStringDetector.hasCustomToString(BarePojo.class));
            check("a class that overrides toString declares one", true,
                    ToStringDetector.declaresToString(NamedPojo.class));
            check("and has a custom one", true,
                    ToStringDetector.hasCustomToString(NamedPojo.class));
            check("a subclass that adds nothing declares no toString", false,
                    ToStringDetector.declaresToString(NamedChild.class));
            check("but it inherits a custom one", true,
                    ToStringDetector.hasCustomToString(NamedChild.class));
            check("inheriting from a bare class inherits nothing custom", false,
                    ToStringDetector.hasCustomToString(BareChild.class));
            check("a subclass that overrides again declares its own", true,
                    ToStringDetector.declaresToString(LoudChild.class));
        } catch (Throwable t) {
            System.out.println("FAIL  unexpected " + t.getClass().getSimpleName() + ": " + t.getMessage());
            failures++;
        }

        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
}

