public class ToStringDetector {

    public static boolean declaresToString(Class<?> c) {
        try {
            c.getDeclaredMethod("toString");
            return true;
        } catch (NoSuchMethodException e) {
            return false;
        }
    }

    public static boolean hasCustomToString(Class<?> c) {
        try {
            Method method = c.getMethod("toString");
            return method.getDeclaringClass() != Object.class;
        } catch (NoSuchMethodException e) {
            return false;
        }
    }
}
